ht: map.get($gen-item, sub-label, line-height);\n    @include transition.apply(color);\n\n    .light & {\n      color: map.get($gen-item, sub-label, color, default, light);\n    }\n\n    .dark & {\n      color: map.get($gen-item, sub-label, color, default, dark);\n    }\n  }\n\n  &.empty {\n    .label {\n      .light & {\n        color: map.get($gen-item, label, color, empty, light);\n      }\n\n      .dark & {\n        color: map.get($gen-item, label, color, empty, dark);\n      }\n    }\n\n    .subLabel {\n      .light & {\n        color: map.get($gen-item, sub-label, color, empty, light);\n      }\n\n      .dark & {\n        color: map.get($gen-item, sub-label, color, empty, dark);\n      }\n    }\n  }\n\n  .selected & {\n    .light & {\n      .label {\n        color: map.get($gen-item, label, color, selected, light);\n      }\n\n      .subLabel {\n        color: map.get($gen-item, sub-label, color, selected, light);\n      }\n    }\n\n    .dark & {\n      .label {\n        color: map.get($gen-item, label, color, selected, dark);\n      }\n\n      .subLabel {\n        color: map.get($gen-item, sub-label, color, selected, dark);\n      }\n    }\n  }\n}\n","////\n/// @group spacing\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'functions/list';\n\n@mixin -spacing(\n  $prop,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('margin' 'padding', $prop) {\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\n  }\n\n  @if $top and $right and $bottom and $left { // all directions specified\n    @if $right == $left {\n      @if $top == $bottom {\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\n          #{$prop}: $top;\n        } @else { // $top (== $bottom) != $right (== $left)\n          #{$prop}: $top $right;\n        }\n      } @else { // $top != $bottom, but $right == $left\n        #{$prop}: $top $right $bottom;\n      }\n    } @else { // $right != $left\n      #{$prop}: $top $right $bottom $left;\n    }\n  } @else { // not all directions specified\n    @if $top {\n      #{$prop}-top: $top;\n    }\n\n    @if $right {\n      #{$prop}-right: $right;\n    }\n\n    @if $bottom {\n      #{$prop}-bottom: $bottom;\n    }\n\n    @if $left {\n      #{$prop}-left: $left;\n    }\n  }\n}\n\n// margin\n\n@mixin margin(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: margin,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias margin()\n///\n@mixin m(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include margin(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-axis()\n///\n@mixin margin-axis($horizontal: null, $vertical: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-center {\n  @include margin($x: auto);\n}\n\n///\n/// @alias margin-center()\n///\n@mixin mx-auto {\n  @include margin-center;\n}\n\n@mixin margin-middle {\n  @include margin($y: auto);\n}\n\n///\n/// @alias margin-middle()\n///\n@mixin my-auto {\n  @include margin-middle;\n}\n\n@mixin margin-all($margin) {\n  @include margin($all: $margin);\n}\n\n///\n/// @alias margin-all()\n///\n@mixin margin-square($margin) {\n  @include margin-all($margin);\n}\n\n@mixin margin-auto {\n  @include margin-all(auto);\n}\n\n///\n/// @alias margin-auto()\n///\n@mixin m-auto {\n  @include margin-auto;\n}\n\n@mixin margin-none {\n  @include margin-all(0);\n}\n\n///\n/// @alias margin-none()\n///\n@mixin m-none {\n  @include margin-none;\n}\n\n///\n/// @alias m-none()\n///\n@mixin m-0 {\n  @include m-none;\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-xy()\n///\n@mixin margin-axis($vertical: null, $horizontal: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-x($x: null) {\n  @include margin($x: $x);\n}\n\n///\n/// @alias margin-x()\n///\n@mixin mx($x: null) {\n  @include margin-x($x: $x);\n}\n\n@mixin mx-none {\n  @include mx($x: 0);\n}\n\n///\n/// @alias mx-none()\n///\n@mixin mx-0 {\n  @include mx-none;\n}\n\n@mixin margin-y($y: null) {\n  @include margin($y: $y);\n}\n\n///\n/// @alias margin-y()\n///\n@mixin my($y: null) {\n  @include margin-y($y: $y);\n}\n\n@mixin my-none {\n  @include my($y: 0);\n}\n\n///\n/// @alias my-none()\n///\n@mixin my-0 {\n  @include my-none;\n}\n\n@mixin margin-top($top: null) {\n  @include margin($top: $top);\n}\n\n///\n/// @alias margin-top()\n///\n@mixin mt($top: null) {\n  @include margin-top($top);\n}\n\n@mixin mt-none {\n  @include mt(0);\n}\n\n///\n/// @alias mt-none()\n///\n@mixin mt-0 {\n  @include mt-none;\n}\n\n@mixin margin-right($right: null) {\n  @include margin($right: $right);\n}\n\n///\n/// @alias margin-right()\n///\n@mixin mr($right: null) {\n  @include margin-right($right);\n}\n\n@mixin mr-none {\n  @include mr($right: 0);\n}\n\n///\n/// @alias mr-none()\n///\n@mixin mr-0 {\n  @include mr-none;\n}\n\n@mixin margin-bottom($bottom: null) {\n  @include margin($bottom: $bottom);\n}\n\n///\n/// @alias margin-bottom()\n///\n@mixin mb($bottom: null) {\n  @include margin-bottom($bottom: $bottom);\n}\n\n@mixin mb-none {\n  @include mb($bottom: 0);\n}\n\n///\n/// @alias mb-none()\n///\n@mixin mb-0 {\n  @include mb-none;\n}\n\n@mixin margin-left($left: null) {\n  @include margin($left: $left);\n}\n\n///\n/// @alias margin-left()\n///\n@mixin ml($left: null) {\n  @include margin-left($left: $left);\n}\n\n@mixin ml-none {\n  @include ml($left: 0);\n}\n\n///\n/// @alias ml-none()\n///\n@mixin ml-0 {\n  @include ml-none;\n}\n\n// padding\n\n@mixin padding(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: padding,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias padding()\n///\n@mixin p(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include padding(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin padding-xy($x: null, $y: null) {\n  @include padding($x: $x, $y: $y);\n}\n\n///\n/// @alias padding-xy()\n///\n@mixin padding-axis($horizontal: null, $vertical: null) {\n  @include padding-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin padding-all($padding) {\n  @include padding($all: $padding);\n}\n\n///\n/// @alias padding-all()\n///\n@mixin padding-square($padding) {\n  @include padding-all($padding);\n}\n\n@mixin padding-none {\n  @include padding-all(0);\n}\n\n///\n/// @alias padding-none()\n///\n@mixin p-none {\n  @include padding-none;\n}\n\n///\n/// @alias p-none()\n///\n@mixin p-0 {\n  @include p-none;\n}\n\n@mixin padding-x($x: null) {\n  @include padding($x: $x);\n}\n\n///\n/// @alias padding-x()\n///\n@mixin px($x: null) {\n  @include padding-x($x);\n}\n\n@mixin px-none {\n  @include px(0);\n}\n\n///\n/// @alias px-none()\n///\n@mixin px-0 {\n  @include px-none;\n}\n\n@mixin padding-y($y: null) {\n  @include padding($y: $y);\n}\n\n///\n/// @alias padding-y()\n///\n@mixin py($y: null) {\n  @include padding-y($y);\n}\n\n@mixin py-none {\n  @include py(0);\n}\n\n///\n/// @alias py-none()\n///\n@mixin py-0 {\n  @include py-none;\n}\n\n@mixin padding-top($top: null) {\n  @include padding($top: $top);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt($top: null) {\n  @include padding-top($top);\n}\n\n@mixin pt-none {\n  @include pt(0);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt-0 {\n  @include pt-none;\n}\n\n@mixin padding-right($right: null) {\n  @include padding($right: $right);\n}\n\n///\n/// @alias padding-right()\n///\n@mixin pr($right: null) {\n  @include padding-right($right);\n}\n\n@mixin pr-none {\n  @include pr(0);\n}\n\n///\n/// @alias pr-none()\n///\n@mixin pr-0 {\n  @include pr-none;\n}\n\n@mixin padding-bottom($bottom: null) {\n  @include padding($bottom: $bottom);\n}\n\n///\n/// @alias padding-bottom()\n///\n@mixin pb($bottom: null) {\n  @include padding-bottom($bottom);\n}\n\n@mixin pb-none {\n  @include pb(0);\n}\n\n///\n/// @alias pb-none()\n///\n@mixin pb-0 {\n  @include pb-none;\n}\n\n@mixin padding-left($left: null) {\n  @include padding($left: $left);\n}\n\n///\n/// @alias padding-left()\n///\n@mixin pl($left: null) {\n  @include padding-left($left);\n}\n\n@mixin pl-none {\n  @include pl(0);\n}\n\n///\n/// @alias pl-none()\n///\n@mixin pl-0 {\n  @include pl-none;\n}\n","////\n/// @group transition\n/// @author Keith Choison\n////\n\n@use 'sass:list';\n@use 'sass:meta';\n@use 'config/animations';\n\n@mixin apply($props...) {\n  $transitions: ();\n\n  @for $i from 1 through list.length($props) {\n    $prop: list.nth($props, $i);\n\n    $name: $prop;\n    $duration: animations.$transition-duration;\n    $function: animations.$transition-function;\n\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\n      $name: list.nth($prop, 1);\n\n      @if list.nth($prop, 2) {\n        $duration: list.nth($prop, 2);\n      }\n\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\n        $function: list.nth($prop, 3);\n      }\n    }\n\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\n  }\n\n  @if list.length($transitions) > 0 {\n    transition: #{list.zip($transitions)};\n  }\n}\n","////\n/// @group aria\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n////\n\n@use 'sass:math';\n@use 'config/colors';\n@use 'functions/color';\n@use 'position';\n@use 'transition';\n\n///\n/// Includes styling for a pseudo-element that displays an outline primarily for accessibility purposes.\n/// Requires at least one unusued pseudo-element (i.e, `::before` or `::after`) in the element this mixin is applied to.\n///\n/// @param {string} $position [relative] - Position of the outline. Specifying `null` will output no `position` property.\n/// @param {string} $pseudo [after] - Pseudo-element to use for displaying the outline. Can be `before` or `after`.\n/// @param {number} $offset [0] - Spacing between the container and the outline. Works just like the CSS `outline-offset` property.\n/// @param {number} $width [2px] - Width (thickness) of the outline. Works just like the CSS `outline-width` and `border-width` properties.\n/// @param {string} $style [solid] - Line style of the outline. Works just like the CSS `outline-style` and `border-style` properties.\n/// @param {string} $color [colors.$blue] - Color of the outline. Works just like the CSS `outline-color` and `border-color` properties.\n/// @param {number} $radius - Optional border radius of the outline. Works just like the CSS `border-radius` property.\n/// @param {number} $opacity [0] - Initial opacity of the outline. Set to `null` to not use opacity as the transition property (`border-color` will be used instead).\n/// @param {number} $z-index - Optional z-index value of the pseudo-element.\n///\n@mixin outline(\n  $position: relative,\n  $pseudo: after,\n  $offset: 4px,\n  $width: 2px,\n  $style: solid,\n  $color: colors.$blue,\n  $radius: null,\n  $opacity: 0,\n  $z-index: null,\n) {\n  @if $position {\n    position: $position;\n  }\n\n  outline: none;\n\n  &::#{$pseudo} {\n    content: '';\n    @include position.absolute($all: -$offset);\n    border: $width $style $color;\n    opacity: $opacity;\n    @include transition.apply(border-color, opacity);\n    pointer-events: none;\n\n    @if $radius {\n      @if math.abs($offset) > 0 {\n        $radius: $radius + math.abs($offset);\n      }\n\n      border-radius: $radius;\n    }\n\n    @if $z-index {\n      z-index: $z-index;\n    }\n\n    @content;\n  }\n}\n\n@mixin outline-hover(\n  $color: colors.$black,\n  $opacity: 0.08,\n) {\n  border-color: $color;\n  opacity: $opacity;\n\n  @content;\n}\n\n@mixin outline-show(\n  $color: colors.$blue,\n  $opacity: 0.88,\n  $duration: 256ms,\n  $timing: ease-out,\n) {\n  border-color: $color;\n  opacity: $opacity;\n  transform: scale(1);\n\n  @content;\n}\n","////\n/// @group position\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:math';\n@use 'sass:meta';\n@use 'functions/list';\n\n///\n/// @access private\n///\n@mixin -inset(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if $top {\n    top: $top;\n  }\n\n  @if $right {\n    right: $right;\n  }\n\n  @if $bottom {\n    bottom: $bottom;\n  }\n\n  @if $left {\n    left: $left;\n  }\n}\n\n@mixin inset(\n  $all: null,\n  $a: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $t: null,\n  $right: null,\n  $r: null,\n  $bottom: null,\n  $b: null,\n  $left: null,\n  $l: null,\n) {\n  @include -inset(\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\n  );\n}\n\n@mixin inset-all($all) {\n  @include inset($all: $all);\n}\n\n@mixin inset-none {\n  @include inset-all(0);\n}\n\n///\n/// @alias inset-none()\n///\n@mixin inset-0 {\n  @include inset-none;\n}\n\n@mixin inset-xy($x: null, $y: null) {\n  @include inset($x: $x, $y: $y);\n}\n\n@mixin inset-x($x) {\n  @include inset-xy($x: $x);\n}\n\n@mixin inset-x-none {\n  @include inset-x(0);\n}\n\n///\n/// @alias inset-x-none()\n///\n@mixin inset-x-0 {\n  @include inset-x-none;\n}\n\n@mixin inset-y($y) {\n  @include inset-xy($y: $y);\n}\n\n@mixin inset-y-none {\n  @include inset-y(0);\n}\n\n///\n/// @alias inset-y-none()\n///\n@mixin inset-y-0 {\n  @include inset-y-none;\n}\n\n@mixin top($top) {\n  @include inset($top: $top);\n}\n\n@mixin top-none {\n  @include top(0);\n}\n\n///\n/// @alias top-none()\n///\n@mixin top-0 {\n  @include top-none;\n}\n\n@mixin right($right) {\n  @include inset($right: $right);\n}\n\n@mixin right-none {\n  @include right(0);\n}\n\n///\n/// @alias right-none()\n///\n@mixin right-0 {\n  @include right-none;\n}\n\n@mixin bottom($bottom) {\n  @include inset($bottom: $bottom);\n}\n\n@mixin bottom-none {\n  @include bottom(0);\n}\n\n///\n/// @alias bottom-none()\n///\n@mixin bottom-0 {\n  @include bottom-none;\n}\n\n@mixin left($left) {\n  @include inset($left: $left);\n}\n\n@mixin left-none {\n  @include left(0);\n}\n\n///\n/// @alias left-none()\n///\n@mixin left-0 {\n  @include left-none;\n}\n\n@mixin unset-all {\n  @include inset-all(unset);\n}\n\n// translate\n\n@mixin translate(\n  $x: null,\n  $y: null,\n) {\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\n    @if $x and $x != 0 and $y and $y != 0 {\n      transform: translate($x, $y);\n    } @else if $x and $x != 0 {\n      transform: translateX($x);\n    } @else if $y and $y != 0 {\n      transform: translateY($y);\n    }\n  }\n}\n\n///\n/// @access private\n///\n@mixin -position(\n  $position: relative,\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('relative' 'absolute' 'fixed' 'sticky', $position) {\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\n  }\n\n  position: $position;\n  @include inset(\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n// relative\n\n@mixin relative {\n  @include -position($position: relative);\n}\n\n///\n/// @alias relative()\n///\n@mixin rel {\n  @include relative;\n}\n\n// absolute\n\n@mixin absolute(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @include -position(\n    $position: absolute,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n///\n/// @alias absolute()\n///\n@mixin abs(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include absolute(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin absolute-axis($horizontal: null, $vertical: null) {\n  @include absolute-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-all($margin) {\n  @include absolute($all: $margin);\n}\n\n///\n/// @alias absolute-all()\n///\n@mixin absolute-square($margin) {\n  @include absolute-all($margin);\n}\n\n@mixin absolute-fill {\n  @include absolute-all(0);\n}\n\n///\n/// @alias absolute-fill()\n///\n@mixin abs-fill {\n  @include absolute-fill;\n}\n\n@mixin absolute-0 {\n  @include absolute-fill;\n}\n\n///\n/// @alias absolute-0()\n///\n@mixin abs-0 {\n  @include absolute-0;\n}\n\n@mixin absolute-xy($x: null, $y: null) {\n  @include absolute($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin abs-xy($x: null, $y: null) {\n  @include absolute-xy($x: $x, $y: $y);\n}\n\n///\n/// @alias absolute-xy()\n///\n@mixin absolute-axis($vertical: null, $horizontal: null) {\n  @include absolute-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin absolute-x($x) {\n  @include absolute-xy($x: $x);\n}\n\n///\n/// @alias absolute-x()\n///\n@mixin abs-x($x) {\n  @include absolute-x($x);\n}\n\n@mixin absolute-y($y) {\n  @include absolute-xy($y: $y);\n}\n\n///\n/// @alias absolute-y()\n///\n@mixin abs-y($y) {\n  @include absolute-y($y);\n}\n\n@mixin absolute-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  $translate-x: if($x, -$x, null);\n  $translate-y: if($y, -$y, null);\n\n  @if $translate-x and math.unit($translate-x) != '%' { // e.g., px\n    $translate-x: 0;\n  }\n\n  @if $translate-y and math.unit($translate-y) != '%' {\n    $translate-y: 0;\n  }\n\n  @include absolute(\n    $top: if($y-prop == top, $y, null),\n    $right: if($x-prop == right, $x, null),\n    $bottom: if($y-prop == bottom, $y, null),\n    $left: if($x-prop == left, $x, null),\n  );\n\n  @include translate($x: $translate-x, $y: $translate-y);\n}\n\n///\n/// @alias absolute-center()\n///\n@mixin abs-anchor(\n  $x: null,\n  $y: null,\n  $x-prop: left,\n  $y-prop: top,\n) {\n  @include absolute-anchor($x: $x, $y: $y, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n@mixin absolute-center($x-prop: left, $y-prop: top) {\n  @include absolute-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n///\n/// @alias absolute-center()\n///\n@mixin abs-center($x-prop: left, $y-prop: top) {\n  @include absolute-center($x-prop: $x-prop, $y-prop: $y-prop);\n}\n\n// fixed\n\n@mixin fixed(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @include -position(\n    $position: fixed,\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n@mixin fixed-xy($x: null, $y: null) {\n  @include fixed($x: $x, $y: $y);\n}\n\n///\n/// @alias fixed-xy()\n///\n@mixin fixed-axis($horizontal: null, $vertical: null) {\n  @include fixed-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin fixed-all($margin) {\n  @include fixed($all: $margin);\n}\n\n///\n/// @alias fixed-all()\n///\n@mixin fixed-square($margin) {\n  @include fixed-all($margin);\n}\n\n