  flex: 1;\n  max-width: calc(100% - 26px - 12px);\n  @include spacing.ml(8px);\n\n  strong {\n    font-weight: 500;\n  }\n}\n\n.format {\n  // max-width: 100%;\n  @include spacing.margin($bottom: 2px);\n  font-size: 10px;\n  letter-spacing: 0.25px;\n  text-transform: uppercase;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  opacity: 0.6;\n  overflow: hidden;\n}\n\n.honkName {\n  // @include font.apply(fonts.$mono);\n  font-weight: 500;\n  font-size: 12px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  opacity: 0.4;\n  overflow: hidden;\n  @include transition.apply(opacity);\n\n  .saved & {\n    opacity: 1;\n  }\n}\n\n.players {\n  @include flex.row-start;\n  // max-width: 100%;\n}\n\n.username {\n  // max-width: 44%;\n  @include flex.row($align: center);\n  font-weight: 500;\n  font-size: 12px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  overflow: hidden;\n  @include transition.apply(color);\n}\n\n.usernameIcon {\n  width: 12px;\n  min-width: 12px;\n  height: 12px;\n  min-height: 12px;\n  @include spacing.margin($left: 2px);\n  color: inherit;\n  transform: scale(1.1);\n}\n\n.versus {\n  @include spacing.padding($x: 5px);\n  font-weight: 600;\n  font-size: 9px;\n  text-transform: uppercase;\n  opacity: 0.6;\n\n  &.noPlayerName {\n    @include spacing.padding($left: 0);\n  }\n}\n\n.morePlayers {\n  @include spacing.margin($left: 3px);\n  font-weight: 500;\n  font-size: 9px;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  opacity: 0.6;\n  overflow: hidden;\n}\n\n@keyframes undo-overlay-fade-in {\n  0% {\n    opacity: 0;\n  }\n\n  100% {\n    opacity: 1;\n  }\n}\n\n.undoOverlay {\n  @include position.absolute-fill;\n  @include flex.row-center;\n  @include font.apply(fonts.$primary, ( font-weight: 500 ));\n  font-size: 10px;\n  text-transform: uppercase;\n  backdrop-filter: blur(4px);\n  border-radius: 12px;\n  animation: undo-overlay-fade-in ease 300ms;\n  @include transition.apply(color);\n\n  [data-showdex-scheme='light'] & {\n    color: color.shade(colors.$red, 16%);\n  }\n\n  [data-showdex-scheme='dark'] & {\n    color: colors.$red;\n  }\n}\n\n.removeButton {\n  @include position.absolute($top: 24px, $right: 12px);\n  width: 16px;\n  height: 16px;\n  border-radius: 100px;\n  opacity: 0;\n  @include transition.apply(top, color, opacity);\n  pointer-events: none;\n\n  i {\n    font-size: 16px;\n  }\n\n  div.container:not(.removing):hover &, div.container:not(.removing):focus & {\n    top: 10px;\n    opacity: 1;\n    pointer-events: all;\n  }\n\n  [data-showdex-scheme='light'] & {\n    color: color.alpha(colors.$black, 0.4);\n  }\n\n  [data-showdex-scheme='dark'] & {\n    color: color.alpha(colors.$white, 0.4);\n  }\n\n  @include aria.outline(\n    $position: null,\n    $offset: 3px,\n    $radius: 100px,\n  );\n\n  &:hover {\n    [data-showdex-scheme='light'] & {\n      color: color.alpha(color.shade(colors.$red, 12%), 0.94);\n      // background-color: color.alpha(colors.$black, 0.12);\n    }\n\n    [data-showdex-scheme='dark'] & {\n      color: color.alpha(colors.$red, 0.94);\n      // background-color: color.alpha(colors.$white, 0.12);\n    }\n\n    &::after {\n      [data-showdex-scheme='light'] & {\n        @include aria.outline-hover;\n      }\n\n      [data-showdex-scheme='dark'] & {\n        @include aria.outline-hover($color: colors.$white);\n      }\n    }\n  }\n\n  &:focus::after {\n    [data-showdex-scheme='light'] &, [data-showdex-scheme='dark'] & {\n      @include aria.outline-show;\n    }\n  }\n}\n","///\n/// @group flex\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n///\n\n///\n/// @access private\n///\n@mixin -flex(\n  $direction: null,\n  $justify: null,\n  $align: null,\n  $inline: false,\n) {\n  display: if($inline, inline-flex, flex);\n\n  @if $direction and $direction != row {\n    flex-direction: $direction;\n  }\n\n  @if $justify and $justify != flex-start {\n    justify-content: $justify;\n  }\n\n  @if $align and $align != stretch {\n    align-items: $align;\n  }\n}\n\n// rows\n\n@mixin row(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include -flex(\n    if($reverse, row-reverse, row),\n    $justify,\n    $align,\n    $inline,\n  );\n}\n\n@mixin row-stretch($reverse: false, $inline: false) {\n  @include row(stretch, stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-stretch()\n///\n@mixin stretch($reverse: false, $inline: false) {\n  @include row-stretch($reverse, $inline);\n}\n\n@mixin row-start($align: center, $reverse: false, $inline: false) {\n  @include row(flex-start, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-start()\n///\n@mixin start($align: center, $reverse: false, $inline: false) {\n  @include row-start($align, $reverse, $inline);\n}\n\n@mixin row-start-stretch($reverse: false, $inline: false) {\n  @include row-start(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-start-stretch()\n///\n@mixin start-stretch($reverse: false, $inline: false) {\n  @include row-start-stretch($reverse, $inline);\n}\n\n@mixin row-center($align: center, $reverse: false, $inline: false) {\n  @include row(center, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-center()\n///\n@mixin center($align: center, $reverse: false, $inline: false) {\n  @include row-center($align, $reverse, $inline);\n}\n\n@mixin row-center-stretch($reverse: false, $inline: false) {\n  @include row-center(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-center-stretch()\n///\n@mixin center-stretch($reverse: false, $inline: false) {\n  @include row-center-stretch($reverse, $inline);\n}\n\n@mixin row-end($align: center, $reverse: false, $inline: false) {\n  @include row(flex-end, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-end()\n///\n@mixin end($align: center, $reverse: false, $inline: false) {\n  @include row-end($align, $reverse, $inline);\n}\n\n@mixin row-end-stretch($reverse: false, $inline: false) {\n  @include row-end(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-end-stretch()\n///\n@mixin end-stretch($reverse: false, $inline: false) {\n  @include row-end-stretch($reverse, $inline);\n}\n\n@mixin row-between($align: center, $reverse: false, $inline: false) {\n  @include row(space-between, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-between()\n///\n@mixin between($align: center, $reverse: false, $inline: false) {\n  @include row-between($align, $reverse, $inline);\n}\n\n@mixin row-between-stretch($reverse: false, $inline: false) {\n  @include row-between(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-between-stretch()\n///\n@mixin between-stretch($reverse: false, $inline: false) {\n  @include row-between-stretch($reverse, $inline);\n}\n\n@mixin row-around($align: center, $reverse: false, $inline: false) {\n  @include row(space-around, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-around()\n///\n@mixin around($align: center, $reverse: false, $inline: false) {\n  @include row-around($align, $reverse, $inline);\n}\n\n@mixin row-around-stretch($reverse: false, $inline: false) {\n  @include row-around(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-around-stretch()\n///\n@mixin around-stretch($reverse: false, $inline: false) {\n  @include row-around-stretch($reverse, $inline);\n}\n\n@mixin row-evenly($align: center, $reverse: false, $inline: false) {\n  @include row(space-evenly, $align, $reverse, $inline);\n}\n\n///\n/// @alias row-evenly()\n///\n@mixin evenly($align: center, $reverse: false, $inline: false) {\n  @include row-evenly($align, $reverse, $inline);\n}\n\n@mixin row-evenly-stretch($reverse: false, $inline: false) {\n  @include row-evenly(stretch, $reverse, $inline);\n}\n\n///\n/// @alias row-evenly-stretch()\n///\n@mixin evenly-stretch($reverse: false, $inline: false) {\n  @include row-evenly-stretch($reverse, $inline);\n}\n\n// columns\n\n@mixin column(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include -flex(\n    if($reverse, column-reverse, column),\n    $justify,\n    $align,\n    $inline,\n  );\n}\n\n///\n/// @alias column()\n///\n@mixin col(\n  $justify: null,\n  $align: null,\n  $reverse: false,\n  $inline: false,\n) {\n  @include column($justify, $align, $reverse, $inline);\n}\n\n@mixin column-stretch($reverse: false, $inline: false) {\n  @include column(stretch, stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-stretch()\n///\n@mixin col-stretch($reverse: false, $inline: false) {\n  @include column-stretch($reverse, $inline);\n}\n\n@mixin column-start($align: center, $reverse: false, $inline: false) {\n  @include column(flex-start, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-start()\n///\n@mixin col-start($align: center, $reverse: false, $inline: false) {\n  @include column-start($align, $reverse, $inline);\n}\n\n@mixin column-start-stretch($reverse: false, $inline: false) {\n  @include column-start(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-start-stretch()\n///\n@mixin col-start-stretch($reverse: false, $inline: false) {\n  @include column-start-stretch($reverse, $inline);\n}\n\n@mixin column-center($align: center, $reverse: false, $inline: false) {\n  @include column(center, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-center()\n///\n@mixin col-center($align: center, $reverse: false, $inline: false) {\n  @include column-center($align, $reverse, $inline);\n}\n\n@mixin column-center-stretch($reverse: false, $inline: false) {\n  @include column-center(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-center-stretch()\n///\n@mixin col-center-stretch($reverse: false, $inline: false) {\n  @include column-center-stretch($reverse, $inline);\n}\n\n@mixin column-end($align: center, $reverse: false, $inline: false) {\n  @include column(flex-end, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-end()\n///\n@mixin col-end($align: center, $reverse: false, $inline: false) {\n  @include column-end($align, $reverse, $inline);\n}\n\n@mixin column-end-stretch($reverse: false, $inline: false) {\n  @include column-end(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-end-stretch()\n///\n@mixin col-end-stretch($reverse: false, $inline: false) {\n  @include column-end-stretch($reverse, $inline);\n}\n\n@mixin column-between($align: center, $reverse: false, $inline: false) {\n  @include column(space-between, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-between()\n///\n@mixin col-between($align: center, $reverse: false, $inline: false) {\n  @include column-between($align, $reverse, $inline);\n}\n\n@mixin column-between-stretch($reverse: false, $inline: false) {\n  @include column-between(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-between-stretch()\n///\n@mixin col-between-stretch($reverse: false, $inline: false) {\n  @include column-between-stretch($reverse, $inline);\n}\n\n@mixin column-around($align: center, $reverse: false, $inline: false) {\n  @include column(space-around, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-around()\n///\n@mixin col-around($align: center, $reverse: false, $inline: false) {\n  @include column-around($align, $reverse, $inline);\n}\n\n@mixin column-around-stretch($reverse: false, $inline: false) {\n  @include column-around(stretch, $reverse, $inline);\n}\n\n///\n/// @alias column-around-stretch()\n///\n@mixin col-around-stretch($reverse: false, $inline: false) {\n  @include column-around-stretch($reverse, $inline);\n}\n\n@mixin column-evenly($align: center, $reverse: false, $inline: false) {\n  @include column(space-evenly, $align, $reverse, $inline);\n}\n\n///\n/// @alias column-evenly()\n///\n@mixin col-evenly($align: center, $reverse: false, $inline: false) {\n  @include column-evenly($align, $reverse, $inline);\n}\n\n@mixin column-evenly-stretch($reverse: false, $inline: false) {\n  @include column-evenly(stretch, $reverse, $inline);\n}\n","////\n/// @group spacing\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'functions/list';\n\n@mixin -spacing(\n  $prop,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('margin' 'padding', $prop) {\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\n  }\n\n  @if $top and $right and $bottom and $left { // all directions specified\n    @if $right == $left {\n      @if $top == $bottom {\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\n          #{$prop}: $top;\n        } @else { // $top (== $bottom) != $right (== $left)\n          #{$prop}: $top $right;\n        }\n      } @else { // $top != $bottom, but $right == $left\n        #{$prop}: $top $right $bottom;\n      }\n    } @else { // $right != $left\n      #{$prop}: $top $right $bottom $left;\n    }\n  } @else { // not all directions specified\n    @if $top {\n      #{$prop}-top: $top;\n    }\n\n    @if $right {\n      #{$prop}-right: $right;\n    }\n\n    @if $bottom {\n      #{$prop}-bottom: $bottom;\n    }\n\n    @if $left {\n      #{$prop}-left: $left;\n    }\n  }\n}\n\n// margin\n\n@mixin margin(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: margin,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias margin()\n///\n@mixin m(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include margin(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-axis()\n///\n@mixin margin-axis($horizontal: null, $vertical: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-center {\n  @include margin($x: auto);\n}\n\n///\n/// @alias margin-center()\n///\n@mixin mx-auto {\n  @include margin-center;\n}\n\n@mixin margin-middle {\n  @include margin($y: auto);\n}\n\n///\n/// @alias margin-middle()\n///\n@mixin my-auto {\n  @include margin-middle;\n}\n\n@mixin margin-all($margin) {\n  @include margin($all: $margin);\n}\n\n///\n/// @alias margin-all()\n///\n@mixin margin-square($margin) {\n  @include margin-all($margin);\n}\n\n@mixin margin-auto {\n  @include margin-all(auto);\n}\n\n///\n/// @alias margin-auto()\n///\n@mixin m-auto {\n  @include margin-auto;\n}\n\n@mixin margin-none {\n  @include margin-all(0);\n}\n\n///\n/// @alias margin-none()\n///\n@mixin m-none {\n  @include margin-none;\n}\n\n///\n/// @alias m-none()\n///\n@mixin m-0 {\n  @include m-none;\n}\n\n@mixin margin-xy($x: null, $y: null) {\n  @include margin($x: $x, $y: $y);\n}\n\n///\n/// @alias margin-xy()\n///\n@mixin margin-axis($vertical: null, $horizontal: null) {\n  @include margin-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin margin-x($x: null) {\n  @include margin($x: $x);\n}\n\n///\n/// @alias margin-x()\n///\n@mixin mx($x: null) {\n  @include margin-x($x: $x);\n}\n\n@mixin mx-none {\n  @include mx($x: 0);\n}\n\n///\n/// @alias mx-none()\n///\n@mixin mx-0 {\n  @include mx-none;\n}\n\n@mixin margin-y($y: null) {\n  @include margin($y: $y);\n}\n\n///\n/// @alias margin-y()\n///\n@mixin my($y: null) {\n  @include margin-y($y: $y);\n}\n\n@mixin my-none {\n  @include my($y: 0);\n}\n\n///\n/// @alias my-none()\n///\n@mixin my-0 {\n  @include my-none;\n}\n\n@mixin margin-top($top: null) {\n  @include margin($top: $top);\n}\n\n///\n/// @alias margin-top()\n///\n@mixin mt($top: null) {\n  @include margin-top($top);\n}\n\n@mixin mt-none {\n  @include mt(0);\n}\n\n///\n/// @alias mt-none()\n///\n@mixin mt-0 {\n  @include mt-none;\n}\n\n@mixin margin-right($right: null) {\n  @include margin($right: $right);\n}\n\n///\n/// @alias margin-right()\n///\n@mixin mr($right: null) {\n  @include margin-right($right);\n}\n\n@mixin mr-none {\n  @include mr($right: 0);\n}\n\n///\n/// @alias mr-none()\n///\n@mixin mr-0 {\n  @include mr-none;\n}\n\n@mixin margin-bottom($bottom: null) {\n  @include margin($bottom: $bottom);\n}\n\n///\n/// @alias margin-bottom()\n///\n@mixin mb($bottom: null) {\n  @include margin-bottom($bottom: $bottom);\n}\n\n@mixin mb-none {\n  @include mb($bottom: 0);\n}\n\n///\n/// @alias mb-none()\n///\n@mixin mb-0 {\n  @include mb-none;\n}\n\n@mixin margin-left($left: null) {\n  @include margin($left: $left);\n}\n\n///\n/// @alias margin-left()\n///\n@mixin ml($left: null) {\n  @include margin-left($left: $left);\n}\n\n@mixin ml-none {\n  @include ml($left: 0);\n}\n\n///\n/// @alias ml-none()\n///\n@mixin ml-0 {\n  @include ml-none;\n}\n\n// padding\n\n@mixin padding(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n  $x: null,\n  $y: null,\n  $all: null,\n) {\n  @include -spacing(\n    $prop: padding,\n    $top: if($top, $top, if($y, $y, $all)),\n    $right: if($right, $right, if($x, $x, $all)),\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\n    $left: if($left, $left, if($x, $x, $all)),\n  );\n}\n\n///\n/// @alias padding()\n///\n@mixin p(\n  $a: null,\n  $x: null,\n  $y: null,\n  $t: null,\n  $r: null,\n  $b: null,\n  $l: null,\n) {\n  @include padding(\n    $all: $a,\n    $x: $x,\n    $y: $y,\n    $top: $t,\n    $right: $r,\n    $bottom: $b,\n    $left: $l,\n  );\n}\n\n@mixin padding-xy($x: null, $y: null) {\n  @include padding($x: $x, $y: $y);\n}\n\n///\n/// @alias padding-xy()\n///\n@mixin padding-axis($horizontal: null, $vertical: null) {\n  @include padding-xy($x: $horizontal, $y: $vertical);\n}\n\n@mixin padding-all($padding) {\n  @include padding($all: $padding);\n}\n\n///\n/// @alias padding-all()\n///\n@mixin padding-square($padding) {\n  @include padding-all($padding);\n}\n\n@mixin padding-none {\n  @include padding-all(0);\n}\n\n///\n/// @alias padding-none()\n///\n@mixin p-none {\n  @include padding-none;\n}\n\n///\n/// @alias p-none()\n///\n@mixin p-0 {\n  @include p-none;\n}\n\n@mixin padding-x($x: null) {\n  @include padding($x: $x);\n}\n\n///\n/// @alias padding-x()\n///\n@mixin px($x: null) {\n  @include padding-x($x);\n}\n\n@mixin px-none {\n  @include px(0);\n}\n\n///\n/// @alias px-none()\n///\n@mixin px-0 {\n  @include px-none;\n}\n\n@mixin padding-y($y: null) {\n  @include padding($y: $y);\n}\n\n///\n/// @alias padding-y()\n///\n@mixin py($y: null) {\n  @include padding-y($y);\n}\n\n@mixin py-none {\n  @include py(0);\n}\n\n///\n/// @alias py-none()\n///\n@mixin py-0 {\n  @include py-none;\n}\n\n@mixin padding-top($top: null) {\n  @include padding($top: $top);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt($top: null) {\n  @include padding-top($top);\n}\n\n@mixin pt-none {\n  @include pt(0);\n}\n\n///\n/// @alias padding-top()\n///\n@mixin pt-0 {\n  @include pt-none;\n}\n\n@mixin padding-right($right: null) {\n  @include padding($right: $right);\n}\n\n///\n/// @alias padding-right()\n///\n@mixin pr($right: null) {\n  @include padding-right($right);\n}\n\n@mixin pr-none {\n  @include pr(0);\n}\n\n///\n/// @alias pr-none()\n///\n@mixin pr-0 {\n  @include pr-none;\n}\n\n@mixin padding-bottom($bottom: null) {\n  @include padding($bottom: $bottom);\n}\n\n///\n/// @alias padding-bottom()\n///\n@mixin pb($bottom: null) {\n  @include padding-bottom($bottom);\n}\n\n@mixin pb-none {\n  @include pb(0);\n}\n\n///\n/// @alias pb-none()\n///\n@mixin pb-0 {\n  @include pb-none;\n}\n\n@mixin padding-left($left: null) {\n  @include padding($left: $left);\n}\n\n///\n/// @alias padding-left()\n///\n@mixin pl($left: null) {\n  @include padding-left($left);\n}\n\n@mixin pl-none {\n  @include pl(0);\n}\n\n///\n/// @alias pl-none()\n///\n@mixin pl-0 {\n  @include pl-none;\n}\n","////\n/// @group font\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:meta';\n@use 'sass:map';\n@use 'config/fonts';\n\n@mixin apply($font, $overrides: null) {\n  $props: (\n    'font-family',\n    'font-stretch',\n    'font-weight',\n  );\n\n  @each $prop in $props {\n    $value: map.get($font, $prop);\n\n    @if meta.type-of($overrides) == map and map.has-key($overrides, $prop) {\n      $value: map.get($overrides, $prop);\n    }\n\n    @if $value {\n      #{$prop}: $value;\n    } @else {\n      @warn 'Font prop `#{$prop}` was ignored because no value was set.';\n    }\n  }\n}\n\n///\n/// Applies the primary font.\n///\n@mixin primary($weight: 400) {\n  @include apply(fonts.$primary, ( font-weight: $weight ));\n}\n\n///\n/// Applies the monospaced font.\n///\n@mixin monospace($weight: 400) {\n  @include apply(fonts.$mono, ( font-weight: $weight ));\n}\n\n///\n/// @alias monospace()\n///\n@mixin mono($weight: 400) {\n  @include monospace($weight);\n}\n","////\n/// @group transition\n/// @author Keith Choison\n////\n\n@use 'sass:list';\n@use 'sass:meta';\n@use 'config/animations';\n\n@mixin apply($props...) {\n  $transitions: ();\n\n  @for $i from 1 through list.length($props) {\n    $prop: list.nth($props, $i);\n\n    $name: $prop;\n    $duration: animations.$transition-duration;\n    $function: animations.$transition-function;\n\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\n      $name: list.nth($prop, 1);\n\n      @if list.nth($prop, 2) {\n        $duration: list.nth($prop, 2);\n      }\n\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\n        $function: list.nth($prop, 3);\n      }\n    }\n\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\n  }\n\n  @if list.length($transitions) > 0 {\n    transition: #{list.zip($transitions)};\n  }\n}\n","$black: #000000;\n$white: #FFFFFF;\n\n$gray-lighter: #EEEEEE; // MD Gray 200\n$gray-light: #BDBDBD; // MD Gray 400\n$gray: #9E9E9E; // MD Gray 500\n$gray-dark: #424242; // MD Gray 800\n$gray-darker: #212121; // MD Gray 900\n$gray-darkest: #121212;\n\n$red: #F44336; // MD Red 500\n$green: #4CAF50; // MD Green 500\n$blue: #2196F3; // MD Blue 500\n\n$pink: #E91E63; // MD Pink 500\n$orange: #FF9800; // MD Orange 500\n$cyan: #00ACC1; // MD Cyan 500\n\n$transparent-black: rgba(0, 0, 0, 0);\n$transparent-white: rgba(255, 255, 255, 0);\n$transparent: $transparent-white;\n\n$showdown-background-light: #EEF2F5;\n$showdown-background-dark: #444444;\n","////\n/// @group position\n/// @access public\n/// @author Keith Choison <keith@tize.io>\n/// @since 0.1.0\n////\n\n@use 'sass:math';\n@use 'sass:meta';\n@use 'functions/list';\n\n///\n/// @access private\n///\n@mixin -inset(\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if $top {\n    top: $top;\n  }\n\n  @if $right {\n    right: $right;\n  }\n\n  @if $bottom {\n    bottom: $bottom;\n  }\n\n  @if $left {\n    left: $left;\n  }\n}\n\n@mixin inset(\n  $all: null,\n  $a: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $t: null,\n  $right: null,\n  $r: null,\n  $bottom: null,\n  $b: null,\n  $left: null,\n  $l: null,\n) {\n  @include -inset(\n    $top: if($top, $top, if($t, $t, if($y, $y, if($a, $a, $all)))),\n    $right: if($right, $right, if($r, $r, if($x, $x, if($a, $a, $all)))),\n    $bottom: if($bottom, $bottom, if($b, $b, if($y, $y, if($a, $a, $all)))),\n    $left: if($left, $left, if($l, $l, if($x, $x, if($a, $a, $all)))),\n  );\n}\n\n@mixin inset-all($all) {\n  @include inset($all: $all);\n}\n\n@mixin inset-none {\n  @include inset-all(0);\n}\n\n///\n/// @alias inset-none()\n///\n@mixin inset-0 {\n  @include inset-none;\n}\n\n@mixin inset-xy($x: null, $y: null) {\n  @include inset($x: $x, $y: $y);\n}\n\n@mixin inset-x($x) {\n  @include inset-xy($x: $x);\n}\n\n@mixin inset-x-none {\n  @include inset-x(0);\n}\n\n///\n/// @alias inset-x-none()\n///\n@mixin inset-x-0 {\n  @include inset-x-none;\n}\n\n@mixin inset-y($y) {\n  @include inset-xy($y: $y);\n}\n\n@mixin inset-y-none {\n  @include inset-y(0);\n}\n\n///\n/// @alias inset-y-none()\n///\n@mixin inset-y-0 {\n  @include inset-y-none;\n}\n\n@mixin top($top) {\n  @include inset($top: $top);\n}\n\n@mixin top-none {\n  @include top(0);\n}\n\n///\n/// @alias top-none()\n///\n@mixin top-0 {\n  @include top-none;\n}\n\n@mixin right($right) {\n  @include inset($right: $right);\n}\n\n@mixin right-none {\n  @include right(0);\n}\n\n///\n/// @alias right-none()\n///\n@mixin right-0 {\n  @include right-none;\n}\n\n@mixin bottom($bottom) {\n  @include inset($bottom: $bottom);\n}\n\n@mixin bottom-none {\n  @include bottom(0);\n}\n\n///\n/// @alias bottom-none()\n///\n@mixin bottom-0 {\n  @include bottom-none;\n}\n\n@mixin left($left) {\n  @include inset($left: $left);\n}\n\n@mixin left-none {\n  @include left(0);\n}\n\n///\n/// @alias left-none()\n///\n@mixin left-0 {\n  @include left-none;\n}\n\n@mixin unset-all {\n  @include inset-all(unset);\n}\n\n// translate\n\n@mixin translate(\n  $x: null,\n  $y: null,\n) {\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\n    @if $x and $x != 0 and $y and $y != 0 {\n      transform: translate($x, $y);\n    } @else if $x and $x != 0 {\n      transform: translateX($x);\n    } @else if $y and $y != 0 {\n      transform: translateY($y);\n    }\n  }\n}\n\n///\n/// @access private\n///\n@mixin -position(\n  $position: relative,\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $right: null,\n  $bottom: null,\n  $left: null,\n) {\n  @if not list.includes('relative' 'absolute' 'fixed' 'sticky', $position) {\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\n  }\n\n  position: $position;\n  @include inset(\n    $all: $all,\n    $x: $x,\n    $y: $y,\n    $top: $top,\n    $right: $right,\n    $bottom: $bottom,\n    $left: $left,\n  );\n}\n\n// relative\n\n@mixin relative {\n  @include -position($position: relative);\n}\n\n///\n/// @alias relative()\n///\n@mixin rel {\n  @include relative;\n}\n\n// absolute\n\n@mixin absolute(\n  $all: null,\n  $x: null,\n  $y: null,\n  $top: null,\n  $r