 100% {\n    transform: translate(-50%, 8px);\n  }\n}\n\n.minarexIcon {\n  @include position.abs($r: -94px, $b: -12px, $l: unset);\n  width: 296px;\n  animation: minarex-animation 4s ease-in infinite alternate;\n  @include transition.apply(left, right, opacity);\n\n  &:not(.shady) :global(#sunglasses) {\n    display: none;\n  }\n\n  .smol & {\n    @include position.abs($r: unset, $l: 74%);\n  }\n\n  .verySmol & {\n    @include position.abs($l: 64%);\n    width: 248px;\n  }\n}\n\n.topContent {\n  flex: 1;\n  width: 100%;\n  @include spacing.px(24px);\n}\n\n.banner {\n  @include position.rel;\n  @include flex.col-center;\n  @include spacing.pt(32px);\n  text-align: center;\n  user-select: none;\n  touch-action: none;\n}\n\n.authors {\n  @include flex.row-center;\n  font-weight: 300;\n  font-size: 12px;\n  text-transform: uppercase;\n  opacity: 0.8;\n}\n\n.ampersand {\n  @include spacing.mx(12px);\n}\n\n.authorButton {\n  @include font.primary;\n  color: inherit;\n\n  .label {\n    @include spacing.mr(-0.2em);\n    font-size: 12px;\n    color: inherit;\n    letter-spacing: 0.2em;\n    text-transform: uppercase;\n  }\n}\n\n.presents {\n  @include spacing.mr(-0.2em);\n  font-weight: 300;\n  font-size: 12px;\n  letter-spacing: 0.2em;\n  text-transform: uppercase;\n  opacity: 0.8;\n}\n\n.extensionName {\n  @include spacing.mr(-0.2em);\n  font-weight: 700;\n  font-size: 40px;\n  color: colors.$transparent;\n  letter-spacing: 0.2em;\n  text-transform: uppercase;\n  text-shadow: 0 0 16px color.alpha(colors.$black, 0.32);\n  background: linear-gradient(65deg, #4A9AC7 1%, #F148CC 99%) 0 0 / 100% 100%;\n  background-clip: text;\n  @include transition.apply(\n    (margin-right, 10s),\n    (letter-spacing, 10s),\n    (background-position, 10s),\n    (background-size, 10s),\n  );\n\n  &:hover {\n    @include spacing.mr(-0.5em);\n    letter-spacing: 0.5em;\n    background-position: 50% 0;\n    background-size: 200% 100%;\n  }\n\n  [data-showdex-theme='mina'] & {\n    background: lin